import { createClient } from 'supabase';
import Papa from 'papaparse';
const RAW='https://raw.githubusercontent.com/olbauday/FPL-Core-Insights/main/data';
const n=(v:any)=>v===undefined||v===null||v===''?0:Number(v)||0;
const i=(v:any)=>Math.round(n(v));
async function csv(url:string){const r=await fetch(url);if(!r.ok){if(r.status===404)return [];throw new Error(`${r.status} ${url}`)}const t=await r.text();return Papa.parse(t,{header:true,skipEmptyLines:true}).data as any[];}
Deno.serve(async()=>{
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}});
 const {data:run,error:re}=await sb.from('source_sync_runs').insert({source:'team_priors',status:'running'}).select('id').single();if(re)return Response.json({ok:false,error:re.message},{status:500});
 try{
  const current=await csv(`${RAW}/2026-2027/teams.csv`);for(const t of current){const {error}=await sb.from('teams').update({team_code:i(t.code),elo:n(t.elo)||null}).eq('fpl_team_id',i(t.id));if(error)throw error;}
  const oldTeams=await csv(`${RAW}/2025-2026/teams.csv`);const codeToMeta=new Map<number,any>();for(const t of oldTeams)codeToMeta.set(i(t.code),t);
  const agg=new Map<number,any>();const ensure=(code:number)=>{const meta=codeToMeta.get(code);let a=agg.get(code);if(!a){a={season:'2025-2026',team_code:code,team_name:meta?.name||null,matches:0,goals_for:0,goals_against:0,xg_for:0,xg_against:0,xgot_for:0,xgot_against:0,shots_for:0,shots_against:0,shots_on_target_for:0,shots_on_target_against:0,big_chances_for:0,big_chances_against:0,possession_sum:0};agg.set(code,a)}return a};
  let rowsSeen=0,gwFiles=0;
  for(let start=1;start<=38;start+=6){const jobs=[];for(let gw=start;gw<start+6&&gw<=38;gw++)jobs.push(csv(`${RAW}/2025-2026/By%20Tournament/Premier%20League/GW${gw}/matches.csv`).then(rows=>({gw,rows})));const results=await Promise.all(jobs);for(const x of results){if(x.rows.length)gwFiles++;for(const m of x.rows){rowsSeen++;const hc=i(m.home_team),ac=i(m.away_team);if(!codeToMeta.has(hc)||!codeToMeta.has(ac))continue;const h=ensure(hc),a=ensure(ac);h.matches++;a.matches++;h.goals_for+=i(m.home_score);h.goals_against+=i(m.away_score);a.goals_for+=i(m.away_score);a.goals_against+=i(m.home_score);h.xg_for+=n(m.home_expected_goals_xg);h.xg_against+=n(m.away_expected_goals_xg);a.xg_for+=n(m.away_expected_goals_xg);a.xg_against+=n(m.home_expected_goals_xg);h.xgot_for+=n(m.home_xg_on_target_xgot);h.xgot_against+=n(m.away_xg_on_target_xgot);a.xgot_for+=n(m.away_xg_on_target_xgot);a.xgot_against+=n(m.home_xg_on_target_xgot);h.shots_for+=i(m.home_total_shots);h.shots_against+=i(m.away_total_shots);a.shots_for+=i(m.away_total_shots);a.shots_against+=i(m.home_total_shots);h.shots_on_target_for+=i(m.home_shots_on_target);h.shots_on_target_against+=i(m.away_shots_on_target);a.shots_on_target_for+=i(m.away_shots_on_target);a.shots_on_target_against+=i(m.home_shots_on_target);h.big_chances_for+=i(m.home_big_chances);h.big_chances_against+=i(m.away_big_chances);a.big_chances_for+=i(m.away_big_chances);a.big_chances_against+=i(m.home_big_chances);h.possession_sum+=n(m.home_possession);a.possession_sum+=n(m.away_possession);}}}
  const rows=[...agg.values()].map(x=>({...x,updated_at:new Date().toISOString()}));for(let k=0;k<rows.length;k+=50){const {error}=await sb.from('historical_team_seasons').upsert(rows.slice(k,k+50),{onConflict:'season,team_code'});if(error)throw error;}
  await sb.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'success',rows_inserted:rows.length+current.length,metadata:{current_teams:current.length,historical_teams:rows.length,gw_files:gwFiles,match_rows_seen:rowsSeen}}).eq('id',run.id);return Response.json({ok:true,current_teams:current.length,historical_teams:rows.length,gw_files:gwFiles,match_rows_seen:rowsSeen});
 }catch(e){const msg=e instanceof Error?e.message:String(e);await sb.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'error',error:msg}).eq('id',run.id);return Response.json({ok:false,error:msg},{status:500})}
});
